function parseCsv(text){
  var rows=[],row=[],field='',i=0,L=text.length,inQ=false;
  while(i<L){
    var c=text[i];
    if(inQ){
      if(c==='"'){ if(text[i+1]==='"'){ field+='"'; i+=2; continue; } inQ=false; i++; continue; }
      if(c==='\n'){ field+='\n'; i++; continue; }
      field+=c; i++; continue;
    }
    if(c==='"'){ inQ=true; i++; continue; }
    if(c===','){ row.push(field); field=''; i++; continue; }
    if(c==='\n'||c==='\r'){ if(c==='\r'&&text[i+1]==='\n')i++; row.push(field); rows.push(row); row=[]; field=''; i++; continue; }
    field+=c; i++;
  }
  row.push(field); rows.push(row);
  return rows.filter(function(r){return r.length>1||r[0]!=='';});
}
function sqlVal(v,dialect){
  if(v===null||v==='') return 'NULL';
  if(/^-?\d+(\.\d+)?$/.test(v)) return v;
  var s=v.replace(/'/g,"''");
  return "'"+s+"'";
}
function csvToSql(text, table, opts){
  opts=opts||{}; var dialect=opts.dialect||'mysql'; var batch=opts.batch||1;
  var rows=parseCsv(text); if(!rows.length) return '';
  var header=rows[0].map(function(h){return h.trim();});
  var body=rows.slice(1);
  if(dialect==='postgres'){
    var cols=header.map(function(h){return '"'+h+'"';}).join(', ');
    var vals=body.map(function(r){return '('+r.map(function(v){return sqlVal(v,dialect);}).join(', ')+')';}).join(', ');
    return 'INSERT INTO '+table+' ('+cols+') VALUES '+vals+';';
  }
  var stmts=[];
  for(var b=0;b<body.length;b+=batch){
    var chunk=body.slice(b,b+batch);
    chunk.forEach(function(r){
      var cols=header.join(', ');
      var vals=r.map(function(v){return sqlVal(v,dialect);}).join(', ');
      stmts.push('INSERT INTO '+table+' ('+cols+') VALUES ('+vals+');');
    });
  }
  return stmts.join('\n');
}
var EXPORTS={parseCsv:parseCsv,sqlVal:sqlVal,csvToSql:csvToSql};


